void Keywords::registerRoutes(httplib::Server& svr, std::shared_ptr<AuthenticationManager> auth)
{
    svr.Get("/ad_accounts/{ad_account_id}/keywords/metrics", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdkeywordsmetricsGetRequest(req, res, auth);
    });
    svr.Post("/ad_accounts/{ad_account_id}/keywords", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdkeywordsPostRequest(req, res, auth);
    });
    svr.Get("/ad_accounts/{ad_account_id}/keywords", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdkeywordsGetRequest(req, res, auth);
    });
    svr.Patch("/ad_accounts/{ad_account_id}/keywords", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdkeywordsPatchRequest(req, res, auth);
    });
    svr.Get("/trends/keywords/{region}/top/{trend_type}", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleTrendskeywordsregiontoptrendTypeGetRequest(req, res, auth);
    });
}

